def solve(p):
    g=G[p+' input']
    h,w=len(g),len(g[0]); bgv=Counter(sum(g,[])).most_common(1)[0][0]
    cc=comps(g,bgv); mo=[c for c in cc if len(c)>1]; seeds=[c for c in cc if len(c)==1]
    out=[row[:] for row in g]
    # precompute all in-bounds, non-overlapping placements for each motif (with each dihedral variant, each anchor of same color)
    allpl=[]
    for mi,mot in enumerate(mo):
        for vn,var in dihs(mot):
            for ar,ac,val in var:
                for r_ in range(h-w):  # placeholder; done below generically
                    pass
    # generic placement generator
    def gens(mot):
        res=[]
        for vn,var in dihs(mot):
            hh=max(x[0] for x in var)+1; ww=max(x[1] for x in var)+1
            for r in range(h-hh+1):
                for c in range(w-ww+1):
                    placed=[(r+a,c+b,z) for a,b,z in var]
                    ps={(p,q) for p,q,_ in placed}
                    # anchor cells: cells with value == seed color... we attach per-seed
                    res.append((vn,placed))
        return res
    for s in sorted(seeds,key=lambda s:s[0][:2]):
        r0,c0=s[0][:2]; v=s[0][2]
        # candidates: placements of any motif (incl. those with a same-color cell) where the placement doesn't overlap other objs; 
        # rank by: if placement contains the seed at a same-color cell -> high base, then maximize distance to other objs
        best=None
        for mot in mo:
            for vn,placed in gens(mot):
                ps={(p,q) for p,q,_ in placed}
                if (r0,c0) not in ps: continue
                vals_at_seed={val for p,q,val in placed if (p,q)==(r0,c0)}
                if v not in vals_at_seed: continue
                objs=set()
                for o_,cl in [(mi,[m_] if False else 0,0) for mi,m_ in []]: pass
                occ=objset() if False else None
        # simpler: compute collisions against (existing objs excluding this seed)
        occ=set()
        for m_ in mo:
            for r_,c_,_ in m_: occ.add((r_,c_))
        for s_ in seeds:
            if s_[0][:2]!=(r0,c0): occ.add(s_[0][:2])
        for mot in mo:
            for vn,placed in gens(mot):
                ps={(p,q) for p,q,_ in placed}
                if (r0,c0) not in ps: continue
                vals_at_seed={val for p,q,val in placed if (p,q)==(r0,c0)}
                if v not in vals_at_seed: continue
                inter=ps&occ-{(r0,c0)}
                if inter: continue
                # distance score
                def mind():
                    return min(max(abs(p-r0),abs(q-c0)) for p,q,_ in placed if (p,q)!=(r0,c0))
                key=(-mind(), len(ps))
                if best is None or key<best[0]:
                    best=(key,vn,placed)
        if best:
            for p,q,z in best[2]:
                out[p][q]=z
    return out
